insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('ae63bead-35d3-4ebd-a187-cdd4c0ef6e8a', 'ada8ee8a-c004-4713-b8ce-914563080494', $$bewegingsvergelijkingen P: x = 8t², y = 4 − 4t² en Q: x = 1 + 3t, y = 4t; figuur 1; P onder en Q boven de x-as op gelijke afstand$$,
   $$wiskunde-b-vwo-2025-ii-beweging-over-twee-lijnen-context1.png$$,
   $$Voor t ≥ 0 beweegt het punt P volgens de bewegingsvergelijkingen:
x_P(t) = 8t²
y_P(t) = 4 − 4t²
Voor t ≥ 0 beweegt tegelijkertijd het punt Q volgens de bewegingsvergelijkingen:
x_Q(t) = 1 + 3t
y_Q(t) = 4t
Hierbij is t de tijd.
Zowel de baan van P als de baan van Q is een deel van een lijn. In figuur 1 zijn deze banen weergegeven.
figuur 1: de banen van P en Q
In figuur 1 is de positie van P en van Q voor een waarde van t weergegeven. Er geldt: − P ligt onder de x-as en Q ligt boven de x-as én − P en Q hebben gelijke afstand tot de x-as.$$, 'inline'),
  ('cf3ae17f-215b-42c1-977b-60f7c656c22a', 'ada8ee8a-c004-4713-b8ce-914563080494', $$Q beweegt met constante snelheid; op t = √5 is de snelheid van P acht keer die van Q$$,
   $$wiskunde-b-vwo-2025-ii-beweging-over-twee-lijnen-context2.png$$,
   $$Punt Q beweegt met constante snelheid over zijn baan. De snelheid v(t) waarmee P over zijn baan beweegt, is niet constant. Er geldt: op t = √5 is de snelheid van P acht keer zo groot als de snelheid van Q.$$, 'inline'),
  ('ceb73fc7-14c1-42e0-aa71-8679d185f16f', 'ada8ee8a-c004-4713-b8ce-914563080494', $$figuur 2: lijnstukken PQ voor t = ½ en t = 1½; helling van PQ is 4/3$$,
   $$wiskunde-b-vwo-2025-ii-beweging-over-twee-lijnen-context3.png$$,
   $$In figuur 2 zijn opnieuw de banen van P en Q weergegeven. Ook is voor t = ½ en voor t = 1½ het lijnstuk PQ weergegeven. De helling van lijnstuk PQ is afhankelijk van t.
figuur 2: de banen van P en Q met de lijnstukken P½Q½ en P1½Q1½
Op een tijdstip t is de helling van lijnstuk PQ gelijk aan 4/3.$$, 'inline'),
  ('b65db6a9-2811-4e14-b4a1-c29c7e1e0615', '094a7abd-07c3-4464-ab25-11f6c8f0bd31', $$zonnepanelen op een plat dak; foto; figuur 1 zijaanzicht met hoeken 30° en 28° en dakrand 172 cm$$,
   $$wiskunde-b-vwo-2025-ii-opbrengst-van-zonnepanelen-context1.png$$,
   $$Op het platte dak van de uitbouw van een huis aan de Parallelweg 10A worden tien even grote zonnepanelen geïnstalleerd. De panelen worden op een stalen frame gemonteerd dat gekanteld is in de richting van het zuiden. Op het horizontale platte dak worden ze in twee rijen achter elkaar geplaatst. Zie de foto.
foto: de zonnepanelen op het dak van de uitbouw
Voorafgaand aan de installatie heeft de leverancier een tekening gemaakt van een zijaanzicht van de opstelling van de panelen. Zie figuur 1, die ook vergroot op de uitwerkbijlage staat. In die situatie verwacht de leverancier maximale energieopbrengst.
figuur 1: zijaanzicht met de panelen PQ en RS, de hoeken van 30° en 28° en de dakrand van 172
Met behulp van deze tekening berekent de leverancier de lengte b (in cm) van de te gebruiken panelen. In de tekening geldt: − de punten P, Q, R en S zijn de hoekpunten van twee panelen; punt P ligt recht boven de linker dakrand en punt S recht boven de rechter dakrand; − de panelen maken een hoek van 30° met het dakoppervlak; − de lengte van de dakrand is 172 cm; − de lengte van PQ en van RS is b cm; − b is zo gekozen dat een zonnestraal door Q, die een hoek van 28° met de dakrand maakt, in R terecht komt; in dat geval ligt de achterste rij panelen niet in de schaduw van de voorste rij panelen.
De rand en de dikte van de zonnepanelen worden in deze opgave buiten beschouwing gelaten.$$, 'inline'),
  ('976511dd-daab-4251-a5d7-048869b4ff8d', '094a7abd-07c3-4464-ab25-11f6c8f0bd31', $$figuur 2: vermogen P_A; P_A = p·cos(qt) + sin(2qt) met 0 < q < 0,4; punten (9; 1,0) en (18; 2,9)$$,
   $$wiskunde-b-vwo-2025-ii-opbrengst-van-zonnepanelen-context2.png$$,
   $$In figuur 2 is het door de zonnepanelen geleverde vermogen P_A in kW op een zonnige 31 augustus uitgezet tegen de tijd t in uren. Uitgaande van de meetwaarden tussen zonsopkomst en zonsondergang is de zwarte vloeiende kromme getekend.
figuur 2: het vermogen P_A in kW tegen t in uren, met de punten bij t = 9 (1,0) en t = 18 (2,9)
De formule bij deze kromme is van de vorm: P_A = p·cos(qt) + sin(2qt) met 0 < q < 0,4
Hierbij is t de tijd in uren met t = 7 om 7.00 uur.
De kromme gaat onder andere door de punten (9; 1,0) en (18; 2,9).$$, 'inline'),
  ('7f92ea43-ec10-44aa-9026-1edc88d0a290', '094a7abd-07c3-4464-ab25-11f6c8f0bd31', $$buren op 10B: energieopbrengst gebruikt voor het opladen van een elektrische auto$$,
   $$wiskunde-b-vwo-2025-ii-opbrengst-van-zonnepanelen-context3.png$$,
   $$De buren op huisnummer 10B hebben ook zonnepanelen. De energieopbrengst van deze panelen wordt direct gebruikt of direct teruggeleverd aan de energiemaatschappij. Eventueel energieverlies wordt in deze opgave buiten beschouwing gelaten.
De energieopbrengst wordt onder andere gebruikt voor het opladen van een elektrische auto. Alle elektriciteit die tijdens het opladen wordt opgewekt, wordt direct in de accu van de auto opgeslagen. Zo wordt de accu met enkel zonne-energie opgeladen.$$, 'inline'),
  ('08b56481-654f-4bdc-8821-725f870b76c2', '094a7abd-07c3-4464-ab25-11f6c8f0bd31', $$P_B = −4,8cos(0,23t); figuur 3; E = ∫ P_B dt; accu 72 kWh om 11.00 uur half vol$$,
   $$wiskunde-b-vwo-2025-ii-opbrengst-van-zonnepanelen-context4.png$$,
   $$Op 31 augustus wordt het geleverde vermogen P_B in kW tussen zonsopkomst en zonsondergang van de zonnepanelen op dit adres in een model benaderd met de formule:
P_B = −4,8cos(0,23t)
Hierbij is t de tijd in uren met t = 7 om 7.00 uur.
De grafiek van P_B is in figuur 3 weergegeven.
figuur 3: de grafiek van P_B in kW tegen t in uren
De energieopbrengst E in kWh tussen twee tijdstippen t₁ en t₂ is te berekenen met de integraal:
E = ∫ van t₁ tot t₂ P_B dt met t₁ < t₂
Om 11.00 uur wordt de elektrische auto aan de laadpaal gekoppeld. De accu, met opslagcapaciteit 72 kWh, is op dat tijdstip voor de helft opgeladen.
Met behulp van de integraal ∫ van 11 tot t₂ P_B dt kan worden berekend hoe lang het duurt tot de accu voor driekwart is opgeladen met de elektriciteit die door de panelen is opgewekt.$$, 'inline'),
  ('cbf04556-6120-422c-a589-791dcf4419f0', '094a7abd-07c3-4464-ab25-11f6c8f0bd31', $$uitwerkbijlage bij vraag 4$$,
   $$wiskunde-b-vwo-2025-ii-opbrengst-van-zonnepanelen-context5.png$$,
   $$Uitwerkbijlage vraag 4: vergrote figuur 1 (zijaanzicht van de zonnepanelen)$$, 'uitwerkbijlage'),
  ('74e78450-f1a1-4a47-bea3-ecfbdb4b6be8', 'bc75d607-73ad-4042-86a2-e5f50e35d0dc', $$f(x) = ln(3x); vierkant PQRS met P en R op f, x_R = 3·x_P; figuur 1$$,
   $$wiskunde-b-vwo-2025-ii-vierkant-en-driehoek-context1.png$$,
   $$De functie f wordt gegeven door f(x) = ln(3x).
In figuur 1 zijn de grafiek van f en het vierkant PQRS weergegeven.
figuur 1: de grafiek van f en het vierkant PQRS
Voor vierkant PQRS geldt: − elke zijde is evenwijdig met de x-as of de y-as; − de hoekpunten P en R liggen op de grafiek van f; − de x-coördinaat van R is drie keer zo groot als de x-coördinaat p van P.$$, 'inline'),
  ('e609b096-7950-4d8d-8cdb-162c59494634', 'bc75d607-73ad-4042-86a2-e5f50e35d0dc', $$lijn y = a snijdt y-as in A en f in B; raaklijn in B snijdt y-as in C; AC = 1; figuur 2$$,
   $$wiskunde-b-vwo-2025-ii-vierkant-en-driehoek-context2.png$$,
   $$De lijn met vergelijking y = a snijdt de y-as in punt A en de grafiek van f in punt B. De raaklijn in het punt B aan de grafiek van f snijdt de y-as in punt C. Zie figuur 2.
figuur 2: de grafiek van f, de lijn y = a en de gestippelde raaklijn in B
Er geldt: voor elke waarde van a heeft lijnstuk AC lengte 1.$$, 'inline'),
  ('c84ab354-60d2-4821-b97a-91a18c6dc943', 'bc75d607-73ad-4042-86a2-e5f50e35d0dc', $$D op raaklijn BC met AD ⊥ BC; figuur 3; L = CD en Opp(ACD) = ½√(L² − L⁴)$$,
   $$wiskunde-b-vwo-2025-ii-vierkant-en-driehoek-context3.png$$,
   $$De lijn door A loodrecht op de raaklijn BC snijdt deze raaklijn in punt D. In figuur 3 is voor een waarde van a de rechthoekige driehoek ACD grijs weergegeven.
figuur 3: de grijze driehoek ACD met AC = 1 en CD = L
Als a varieert, varieert de lengte van zijde CD.
Als L de lengte van zijde CD is, dan geldt voor de oppervlakte van de driehoek:
Opp(ACD) = ½√(L² − L⁴)$$, 'inline'),
  ('966c44d8-2759-4885-a1c5-3227630eee1b', '1ac28d9b-86cb-4f49-9efa-82ee2b352741', $$A(5, 4), B(8, 5) en P(p, q); figuur 1 en 2; P op de x-as met AP = BP$$,
   $$wiskunde-b-vwo-2025-ii-twee-lijnstukken-met-eindpunt-p-context1.png$$,
   $$Gegeven zijn de punten A(5, 4) en B(8, 5). Verder is een punt P(p, q) gegeven dat niet samenvalt met A of B.
In figuur 1 en 2 zijn voor twee posities van P de lijnstukken AP en BP getekend.
figuur 1 en figuur 2: de lijnstukken AP en BP voor twee posities van P
Punt P kan zo worden gekozen, dat P op de x-as ligt en AP en BP even lang zijn.$$, 'inline'),
  ('5a66adec-3ef7-4e6c-b76c-36c44f25a7b7', '1ac28d9b-86cb-4f49-9efa-82ee2b352741', $$AP⃗ 90° tegen de klok in gedraaid geeft AC⃗, BP⃗ 90° met de klok mee geeft BD⃗; M midden van CD; figuur 3 en 4$$,
   $$wiskunde-b-vwo-2025-ii-twee-lijnstukken-met-eindpunt-p-context2.png$$,
   $$Vector AP⃗ wordt 90° tegen de klok in om A gedraaid. Het resultaat is vector AC⃗.
Vector BP⃗ wordt 90° met de klok mee om B gedraaid. Het resultaat is vector BD⃗.
Punt M is het midden van lijnstuk CD.
In figuur 3 en 4 zijn voor twee posities van P de vectoren AP⃗, AC⃗, BP⃗ en BD⃗ weergegeven. Ook zijn het lijnstuk CD en punt M weergegeven.
figuur 3 en figuur 4: de vectoren AP⃗, AC⃗, BP⃗, BD⃗, het lijnstuk CD en punt M voor twee posities van P
De coördinaten van M zijn onafhankelijk van de positie van punt P.$$, 'inline'),
  ('f77d43b9-941e-4f56-994c-b81243aeb87c', 'a2e2ffff-2029-4bf1-8528-884593278ad9', $$f(x) = √x en g(x) = √(x + sin(x)); figuur 1$$,
   $$wiskunde-b-vwo-2025-ii-wortel-en-sinus-context1.png$$,
   $$De functies f en g worden gegeven door f(x) = √x en g(x) = √(x + sin(x)).
In figuur 1 zijn de grafieken van f en g weergegeven.
figuur 1: de grafieken van f en g met de snijpunten S₁ tot en met S₄$$, 'inline'),
  ('b18e332d-d36f-41ce-89eb-11a690cb2e58', 'a2e2ffff-2029-4bf1-8528-884593278ad9', $$snijpunten S₁, S₂, S₃, ...; figuur 2 rond S₂; hellingen in S₂; voor even n is de helling van g in Sₙ twee keer die van f$$,
   $$wiskunde-b-vwo-2025-ii-wortel-en-sinus-context2.png$$,
   $$De oorsprong O is een gemeenschappelijk punt van de twee grafieken. Verder snijden de grafieken elkaar achtereenvolgens in de punten S₁, S₂, S₃, …
In figuur 2 is een deel van figuur 1 rondom snijpunt S₂ vergroot weergegeven. In deze figuur zijn de raaklijnen in S₂ aan de grafiek van f en de grafiek van g gestippeld weergegeven.
figuur 2: de grafieken van f en g rond S₂ met de gestippelde raaklijnen
De helling van de grafiek van f in S₂ is gelijk aan 1/(2√(2π)). De helling van de grafiek van g in S₂ is 1/√(2π), dus twee keer zo groot.
Als n een even getal is, geldt:
In de snijpunten Sₙ is de helling van de grafiek van g twee keer zo groot als de helling van de grafiek van f.$$, 'inline'),
  ('f2b22a5f-129e-4d98-b7e4-6aa1f19f8460', '4fae3739-e36a-4864-bc0f-c2087ba04d85', $$fₐ(x) = |a − x²| · x + 3x voor x ≥ 0 en a > 1½; knik bij x = √a; y_top = 2(⅓a + 1)√(⅓a + 1)$$,
   $$wiskunde-b-vwo-2025-ii-drie-keer-over-de-lijn-context1.png$$,
   $$Voor x ≥ 0 en a > 1½ wordt de functie fₐ gegeven door:
fₐ(x) = |a − x²| · x + 3x
De grafiek van fₐ heeft een knik met x-coördinaat √a. Deze knik verdeelt de grafiek van fₐ in twee delen. Links van deze knik bevindt zich een top van de grafiek van fₐ.
De y-coördinaat van deze top is te schrijven als:
y_top = 2(⅓a + 1)√(⅓a + 1)$$, 'inline'),
  ('0cac5f89-a118-4e34-ae3e-50f3d945d9bf', '4fae3739-e36a-4864-bc0f-c2087ba04d85', $$figuur met f₈, f₂₀, f₃₂ en lijn l: y = 16; aantal snijpunten hangt af van top en knik; drie snijpunten vormen een interval$$,
   $$wiskunde-b-vwo-2025-ii-drie-keer-over-de-lijn-context2.png$$,
   $$In de figuur zijn de grafieken van f₈, f₂₀ en f₃₂ en de lijn l met vergelijking y = 16 weergegeven.
figuur: de grafieken van f₈, f₂₀ en f₃₂ met de gestippelde lijn l
Als a toeneemt, neemt de y-coördinaat 2(⅓a + 1)√(⅓a + 1) van de top toe. Ook de y-coördinaat fₐ(√a) van de knik neemt dan toe.
Het aantal gemeenschappelijke punten van de grafiek van fₐ en lijn l hangt af van deze y-coördinaten. Zo snijden de grafiek van f₈ en lijn l elkaar in één punt. De grafiek van f₂₀ snijdt lijn l in drie punten en de grafiek van f₃₂ snijdt lijn l in één punt.
De waarden van a waarvoor de grafiek van fₐ en lijn l drie snijpunten hebben, vormen een interval.$$, 'inline'),
  ('363098af-e04d-4b87-829e-c69d2d94aca4', '3263567c-85dc-4d13-bd9a-4f509e5ca549', $$f(x) = 10eˣ/(eˣ + 1) − x − 1; figuur 1; raaklijn k: y = 1½x + 4 in D; vlakdeel V tot de verticale lijn door E$$,
   $$wiskunde-b-vwo-2025-ii-vlakdeel-en-rakende-cirkel-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 10eˣ/(eˣ + 1) − x − 1.
In figuur 1 is de grafiek van f weergegeven
figuur 1: de grafiek van f, de lijn k en het grijze vlakdeel V
De grafiek van f snijdt de y-as in het punt D.
De lijn k met vergelijking y = 1½x + 4 raakt de grafiek van f in D. D is het enige punt van de grafiek van f dat op k ligt.
De grafiek van f snijdt de x-as in het punt E.
V is het vlakdeel dat wordt ingesloten door de grafiek van f, lijn k en de verticale lijn door E. V wordt om de x-as gewenteld.$$, 'inline'),
  ('16787f35-928f-4078-850e-402002bab8d5', '3263567c-85dc-4d13-bd9a-4f509e5ca549', $$twee scheve asymptoten met rc −1; figuur 2; y = −x − 1 en y = −x + 9$$,
   $$wiskunde-b-vwo-2025-ii-vlakdeel-en-rakende-cirkel-context2.png$$,
   $$De grafiek van f heeft twee scheve asymptoten met richtingscoëfficiënt −1. In figuur 2 is de grafiek van f met deze asymptoten weergegeven.
figuur 2: de grafiek van f met de twee gestippelde scheve asymptoten
Vergelijkingen van de scheve asymptoten zijn y = −x − 1 en y = −x + 9.$$, 'inline'),
  ('0105d0cb-a8d6-4354-9d58-4df0165e95ba', '3263567c-85dc-4d13-bd9a-4f509e5ca549', $$figuur 3: cirkel met middelpunt M onder de x-as raakt beide asymptoten en de x-as$$,
   $$wiskunde-b-vwo-2025-ii-vlakdeel-en-rakende-cirkel-context3.png$$,
   $$In figuur 3 zijn de twee scheve asymptoten van de grafiek van f weergegeven. Ook is de cirkel met middelpunt M onder de x-as weergegeven. Deze cirkel raakt aan beide scheve asymptoten en aan de x-as.
figuur 3: de asymptoten y = −x − 1 en y = −x + 9 en de cirkel met middelpunt M$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('ecac2541-17d9-4625-be2c-e8375054e979', 'ada8ee8a-c004-4713-b8ce-914563080494', 1,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}, {"domain": "Meetkunde met coördinaten", "subdomain": "Vectoren en inproduct"}]'::jsonb,
   '["bewegingsvergelijkingen", "kwadratische vergelijking", "abc-formule", "exact berekenen"]'::jsonb,
   $$Exact berekenen van een positie waarbij twee bewegende punten even ver van de x-as liggen.$$,
   $$wiskunde-b-vwo-2025-ii-beweging-over-twee-lijnen-vraag1.png$$, $$3p 1 Bereken exact de y-coördinaat van P in dit geval.$$, array['ae63bead-35d3-4ebd-a187-cdd4c0ef6e8a']::uuid[]),
  ('9f0cf520-92f1-40ce-a179-7790b726d716', 'ada8ee8a-c004-4713-b8ce-914563080494', 2,
   '[{"domain": "Meetkunde met coördinaten", "subdomain": "Vectoren en inproduct"}, {"domain": "Differentiaal- en integraalrekening", "subdomain": "Technieken voor differentiëren"}]'::jsonb,
   '["baansnelheid", "snelheidsvector", "afgeleide", "lengte van een vector", "bewijzen"]'::jsonb,
   $$Met de snelheidsvectoren bewijzen dat de baansnelheid van het ene punt acht keer die van het andere is.$$,
   $$wiskunde-b-vwo-2025-ii-beweging-over-twee-lijnen-vraag2.png$$, $$4p 2 Bewijs dat op t = √5 de snelheid van P inderdaad acht keer zo groot is als de snelheid van Q.$$, array['ae63bead-35d3-4ebd-a187-cdd4c0ef6e8a', 'cf3ae17f-215b-42c1-977b-60f7c656c22a']::uuid[]),
  ('68f036a7-7f46-4a36-a4c0-2d98231a2f50', 'ada8ee8a-c004-4713-b8ce-914563080494', 3,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}, {"domain": "Meetkunde met coördinaten", "subdomain": "Algebraïsche methoden in de vlakke meetkunde"}]'::jsonb,
   '["richtingscoëfficiënt", "helling lijnstuk", "bewegingsvergelijkingen", "kwadratische vergelijking", "exact berekenen"]'::jsonb,
